package com.jobsphere.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="user_profiles")
public class UserProfile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="user_id",nullable=false,unique=true) public Long userId; @Column(length=20) public String phone; @Column(length=160) public String location; @Column(length=200) public String university; @Column(length=200) public String degree; @Column(name="graduation_year") public Integer graduationYear; @Column(length=100) public String employmentStatus; @Column(length=200) public String headline; @Column(columnDefinition="TEXT") public String education; @Column(columnDefinition="TEXT") public String skills; @Column(name="soft_skills",columnDefinition="TEXT") public String softSkills; @Column(columnDefinition="TEXT") public String experience; @Column(columnDefinition="TEXT") public String projects; @Column(columnDefinition="TEXT") public String certifications; @Column(name="career_interest",columnDefinition="TEXT") public String careerInterest; @Column(name="career_goal",columnDefinition="TEXT") public String careerGoal; @Column(length=255) public String portfolioUrl; @Column(length=255) public String linkedinUrl; @Column(length=255) public String githubUrl; @Column(name="updated_at",nullable=false) public LocalDateTime updatedAt; }
